// Hand-written `@medusajs/framework` stub for the flowatlas fixture suite.
//
// The real package puts these behind subpaths — `@medusajs/framework/http` and
// `@medusajs/framework/types` — and the fixture imports them from the root,
// because nothing the reader does depends on where they came from. Detection is
// the manifest, the address is the file's path, the verb is the name of the
// export, and the middleware list is found by the name of the call that builds
// it.

export interface MedusaRequest<Body = unknown> {
  params: Record<string, string>;
  query: Record<string, string>;
  body: Body;
}

export interface MedusaResponse<Body = unknown> {
  status(code: number): MedusaResponse<Body>;
  json(body: Body): MedusaResponse<Body>;
}

export type MedusaNextFunction = (error?: unknown) => void;

export type MedusaMiddleware = (
  req: MedusaRequest,
  res: MedusaResponse,
  next: MedusaNextFunction,
) => unknown;

export interface MiddlewareRoute {
  matcher: string | RegExp;
  /** The older spelling of `methods`, which the helper still accepts. */
  method?: string | string[];
  methods?: string[];
  middlewares?: MedusaMiddleware[];
}

export interface MiddlewaresConfig {
  routes: MiddlewareRoute[];
}

export declare function defineMiddlewares(
  config: MiddlewareRoute[] | { routes?: MiddlewareRoute[] },
): MiddlewaresConfig;

export declare function authenticate(actor: string, kinds: string[]): MedusaMiddleware;

export declare function validateBody(shape: unknown): MedusaMiddleware;

/** A handler assembled by a package, with nothing of this repository in it. */
export declare function restHandler(
  config: unknown,
): (req: MedusaRequest, res: MedusaResponse) => Promise<void>;
